// Reine Umformung - die Markdown-Datei hat der Dienst gebaut.
// Hier wird nur in das Format gebracht, das der Master-Ablauf erwartet.
// Bewusst ohne Logik: Alles, was den Inhalt betrifft, steckt in
// mk_md.baue_markdown() und gilt damit fuer die Skript-Kette und fuer
// n8n gleichermassen.
return $input.all().map((item) => {
  const a = item.json;
  const name = a.dateiname || 'dokument.md';
  return {
    json: {
      markdown_filename: name,
      markdown_path: '/files/anythingllm/' + name,
      markdown_content: a.markdown,
      zeichen: a.zeichen,
      seiten: a.seiten,
      tags: a.tags,
      keywords: a.keywords,
      methoden: a.methoden,
    },
    binary: {
      data: {
        data: Buffer.from(a.markdown, 'utf8').toString('base64'),
        mimeType: 'text/markdown',
        fileName: name,
      },
    },
  };
});

// Ablaufplan 3 ist eine Funktion: EIN Element hinein, EIN Element hinaus.
//
// ⛔ Gemessen 23.09. abends: Von 40 Dokumenten kam EINES im Bestand an.
//   39 wurden mit "im Arbeitsbereich nicht wiedergefunden" aussortiert -
//   zu Recht, denn sie wurden nie hochgeladen. Verloren gingen sie hier:
//   Dieser Ablaufplan hatte keinen zugesicherten Rueckgabe-Weg und keinen
//   Fehlerabfang. Scheitert der Markdown-Dienst bei EINEM Dokument, bricht
//   die Unterausfuehrung ab, im Elternteil bricht assignPairedItems, und
//   der ganze Block kommt leer heraus.
//
// ⛔ Derselbe Fehler war am Vormittag in Ablaufplan 2 behoben worden -
//   hier aber nicht. Eine Fundstelle zu reparieren und die anderen nicht
//   zu suchen, ist die teuerste Sorte halber Arbeit ("13 Stellen,
//   3 gefunden", 04.08.).

// --- WAEHLEN ---
const _waehlen = (elemente, name) => {
  const liste = elemente || [];
  const echt = liste.filter(e => e && e.json && e.json.__rueckfall !== true);
  if (echt.length) return [echt[0]];
  const grund = (liste[0] && liste[0].json && liste[0].json.grund)
    || 'die Markdown-Erzeugung hat kein Element geliefert';
  // Leeres Ergebnis MIT Grund: Der Elternteil sortiert die Datei dann
  // ehrlich aus, statt dass der ganze Durchgang leer ausgeht.
  return [{ json: {
    ok: false,
    grund: grund,
    markdown_path: null,
    data: '',
    docling_filename: name || null,
    fehler: 'Markdown-Erzeugung ohne Ergebnis: ' + grund
  } }];
};
// --- ENDE WAEHLEN ---

let _name = '';
try { _name = $('Start').first().json.filename || ''; } catch (e) { _name = ''; }
return _waehlen($input.all(), _name);
